// Regenerates site/src/engine/irregulars-data.js: node scripts/gen-irregulars.js
// Source data is Open English WordNet (https://en-word.net/), licensed CC BY 4.0
// (https://creativecommons.org/licenses/by/4.0/); attribution rides in the
// generated file's header and THIRD-PARTY-NOTICES.
import { writeFile } from 'node:fs/promises';
import { toNorm } from '../site/src/engine/norm.js';
import { candidates } from '../site/src/engine/morphology.js';
import { fetchWordNet } from './wordnet.js';

const OUT = new URL('../site/src/engine/irregulars-data.js', import.meta.url);

function ruleReaches(surface, base) { for (const c of candidates(surface)) if (c === base) return true; return false; }
function lcp(a, b) { let i = 0; while (i < a.length && i < b.length && a[i] === b[i]) i++; return i; }

function reduce(text) {
  const map = new Map();
  for (const line of text.split('\n')) {
    const toks = line.trim().split(/\s+/);
    if (toks.length < 2 || toks[0].includes('_')) continue;   // '_' joins a phrase the engine reduces per token
    const surface = toNorm(toks[0]);
    let base = null, best = -1;
    for (const b of toks.slice(1)) {                          // WordNet may list several bases; take the closest
      const nb = toNorm(b);
      if (nb && lcp(surface, nb) > best) { best = lcp(surface, nb); base = nb; }
    }
    if (base && surface && surface !== base && !ruleReaches(surface, base) && !map.has(surface)) map.set(surface, base);
  }
  return map;
}

const { 'noun.exc': noun, 'verb.exc': verb } = await fetchWordNet(['noun.exc', 'verb.exc']);

const map = new Map([...reduce(noun), ...reduce(verb)]);
const lines = [...map].sort((a, b) => a[0] < b[0] ? -1 : 1).map(([s, b]) => `${s} ${b}`);

const header = `'use strict';

// Generated by scripts/gen-irregulars.js — do not edit by hand. Inflectional
// exceptions: the irregular surface->base pairs no suffix rule can reach (ablaut
// verbs, irregular and Latin/Greek plurals, suppletion). morphology.js parses
// this and overlays its curated core on top.
//
// Source: Open English WordNet 2025 noun.exc + verb.exc (https://en-word.net/).
//   Copyright the Open English WordNet contributors, licensed CC BY 4.0
//   (https://creativecommons.org/licenses/by/4.0/) — free to use and
//   redistribute with attribution; the notice rides here and in
//   THIRD-PARTY-NOTICES.

export const WORDNET_IRREGULARS = \`
${lines.join('\n')}
\`;
`;

await writeFile(OUT, header);
console.log(`Wrote ${OUT.pathname}: ${lines.length} pairs`);
